import { useSearchParams } from 'react-router-dom';
import FilterBar from '../components/FilterBar';
import IssueCard from '../components/IssueCard';
import { assignees, issues, statuses } from '../data/issues';

export default function IssueList() {
  const [searchParams, setSearchParams] = useSearchParams();

  const statusParam = searchParams.get('status');
  const assigneeParam = searchParams.get('assignee');
  const status = statusParam && statuses.some((value) => value === statusParam)
    ? statusParam
    : 'all';
  const assignee = assigneeParam && assignees.includes(assigneeParam)
    ? assigneeParam
    : 'all';

  const updateFilter = (name: 'status' | 'assignee', value: string) => {
    setSearchParams((current) => {
      const next = new URLSearchParams(current);
      if (value === 'all') {
        next.delete(name);
      } else {
        next.set(name, value);
      }
      return next;
    });
  };

  const clearFilters = () => {
    setSearchParams((current) => {
      const next = new URLSearchParams(current);
      next.delete('status');
      next.delete('assignee');
      return next;
    });
  };

  const visible = issues.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  return (
    <section>
      <h1>Issues</h1>
      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={(value) => updateFilter('status', value)}
        onAssigneeChange={(value) => updateFilter('assignee', value)}
        onClear={clearFilters}
      />
      <p className="result-count">
        {visible.length} of {issues.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

