  const status = statuses.some((value) => value === statusParam) ? statusParam! : 'all';
  const assignee = assignees.some((value) => value === assigneeParam) ? assigneeParam! : 'all';

  const updateFilters = (nextStatus: string, nextAssignee: string) => {
    const nextParams = new URLSearchParams(searchParams);

    if (nextStatus === 'all') nextParams.delete('status');
    else nextParams.set('status', nextStatus);

    if (nextAssignee === 'all') nextParams.delete('assignee');
    else nextParams.set('assignee', nextAssignee);

