import { FormEvent, useEffect, useRef, useState } from 'react';
import FilterBar from '../components/FilterBar';
import IssueCard from '../components/IssueCard';
import type { Issue } from '../data/issues';

interface IssueListProps {
  issues: Issue[];
  onCreateIssue: (title: string) => void;
}

export default function IssueList({ issues, onCreateIssue }: IssueListProps) {
  const [status, setStatus] = useState('all');
  const [assignee, setAssignee] = useState('all');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [title, setTitle] = useState('');
  const [titleError, setTitleError] = useState('');
  const titleInput = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isFormOpen) titleInput.current?.focus();
  }, [isFormOpen]);

  const visible = issues.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const trimmedTitle = title.trim();

    if (!trimmedTitle) {
      setTitleError('Title is required');
      titleInput.current?.focus();
      return;
    }

    onCreateIssue(trimmedTitle);
    setTitle('');
    setTitleError('');
    setIsFormOpen(false);
    // Ensure the newly created open issue is visible even if the list was filtered.
    setStatus('all');
    setAssignee('all');
  }

  function closeForm() {
    setIsFormOpen(false);
    setTitle('');
    setTitleError('');
  }

  return (
    <section>
      <div className="issues-heading">
        <h1>Issues</h1>
        <button className="primary-button" type="button" onClick={() => setIsFormOpen(true)}>
          New issue
        </button>
      </div>

      {isFormOpen && (
        <form className="new-issue-form" onSubmit={handleSubmit} noValidate>
          <div className="new-issue-form__heading">
            <h2>New issue</h2>
            <button className="close-button" type="button" onClick={closeForm} aria-label="Close new issue form">
              ×
            </button>
          </div>
          <label htmlFor="new-issue-title">Title</label>
          <input
            ref={titleInput}
            id="new-issue-title"
            name="title"
            type="text"
            value={title}
            aria-invalid={Boolean(titleError)}
            aria-describedby={titleError ? 'new-issue-title-error' : undefined}
            onChange={(event) => {
              setTitle(event.target.value);
              if (titleError && event.target.value.trim()) setTitleError('');
            }}
          />
          {titleError && (
            <p className="field-error" id="new-issue-title-error" role="alert">
              {titleError}
            </p>
          )}
          <div className="new-issue-form__actions">
            <button type="button" className="secondary-button" onClick={closeForm}>
              Cancel
            </button>
            <button type="submit" className="primary-button">
              Create issue
            </button>
          </div>
        </form>
      )}

      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={setStatus}
        onAssigneeChange={setAssignee}
      />
      <p className="result-count">
        {visible.length} of {issues.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

