import { useState } from 'react';
import { BrowserRouter, Navigate, NavLink, Route, Routes } from 'react-router-dom';
import type { Issue } from './data/issues';
import { issues as initialIssues } from './data/issues';
import Dashboard from './pages/Dashboard';
import IssueDetail from './pages/IssueDetail';
import IssueList from './pages/IssueList';
import Settings from './pages/Settings';

export default function App() {
  const [issues, setIssues] = useState<Issue[]>(initialIssues);

  const addIssue = (issue: Issue) => {
    setIssues((current) => [issue, ...current]);
  };

  return (
    <BrowserRouter>
      <header className="topbar">
        <span className="brand">Trackline</span>
        <nav>
          <NavLink to="/" end>
            Dashboard
          </NavLink>
          <NavLink to="/issues">Issues</NavLink>
          <NavLink to="/settings">Settings</NavLink>
        </nav>
      </header>
      <main className="page">
        <Routes>
          <Route path="/" element={<Dashboard issues={issues} />} />
          <Route path="/issues" element={<IssueList issues={issues} onAddIssue={addIssue} />} />
          <Route path="/issues/:id" element={<IssueDetail issues={issues} />} />
          <Route path="/settings" element={<Settings />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </main>
    </BrowserRouter>
  );
}

