import { useState, type FormEvent } from 'react';
import FilterBar from '../components/FilterBar';
import IssueCard from '../components/IssueCard';
import type { Issue } from '../data/issues';

interface IssueListProps {
  issues: Issue[];
  onAddIssue: (issue: Issue) => void;
}

export default function IssueList({ issues, onAddIssue }: IssueListProps) {
  const [status, setStatus] = useState('all');
  const [assignee, setAssignee] = useState('all');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [title, setTitle] = useState('');
  const [titleError, setTitleError] = useState('');

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const trimmedTitle = title.trim();

    if (!trimmedTitle) {
      setTitleError('Title is required.');
      return;
    }

    const nextId = issues.reduce((largest, issue) => Math.max(largest, issue.id), 0) + 1;
    onAddIssue({
      id: nextId,
      title: trimmedTitle,
      description: '',
      status: 'open',
      assignee: 'Unassigned',
      tags: [],
      createdAt: new Date().toISOString().slice(0, 10),
    });
    setTitle('');
    setTitleError('');
    setIsFormOpen(false);
    // Make sure the new open, unassigned issue is not hidden by an active filter.
    setStatus('all');
    setAssignee('all');
  };

  const visible = issues.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  return (
    <section>
      <div className="issues-heading">
        <h1>Issues</h1>
        <button
          className="primary-button"
          type="button"
          onClick={() => {
            setIsFormOpen(true);
            setTitleError('');
          }}
          aria-expanded={isFormOpen}
          aria-controls="new-issue-form"
        >
          New issue
        </button>
      </div>
      {isFormOpen && (
        <form className="new-issue-form" id="new-issue-form" onSubmit={handleSubmit} noValidate>
          <h2>New issue</h2>
          <label htmlFor="issue-title">Title</label>
          <input
            id="issue-title"
            name="title"
            value={title}
            onChange={(event) => {
              setTitle(event.target.value);
              if (titleError) setTitleError('');
            }}
            aria-invalid={Boolean(titleError)}
            aria-describedby={titleError ? 'issue-title-error' : undefined}
            autoFocus
          />
          {titleError && (
            <p className="field-error" id="issue-title-error" role="alert">
              {titleError}
            </p>
          )}
          <div className="new-issue-form__actions">
            <button className="primary-button" type="submit">
              Create issue
            </button>
            <button
              className="secondary-button"
              type="button"
              onClick={() => {
                setIsFormOpen(false);
                setTitle('');
                setTitleError('');
              }}
            >
              Cancel
            </button>
          </div>
        </form>
      )}
      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={setStatus}
        onAssigneeChange={setAssignee}
      />
      <p className="result-count">
        {visible.length} of {issues.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

