    };

    setIssues((currentIssues) => [newIssue, ...currentIssues]);
  }

  return (
    <BrowserRouter>
      <header className="topbar">
        <span className="brand">Trackline</span>
        <nav>
          <NavLink to="/" end>
            Dashboard
