import { useState } from 'react';
import { Link } from 'react-router-dom';
import FilterBar from '../components/FilterBar';
import IssueCard from '../components/IssueCard';
import type { Issue } from '../data/issues';

export default function IssueList({ issues }: { issues: Issue[] }) {
  const [status, setStatus] = useState('all');
  const [assignee, setAssignee] = useState('all');

  const visible = issues.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  return (
    <section>
      <div className="page-heading">
        <h1>Issues</h1>
        <Link to="/issues/new" className="button button--primary">
          New issue
        </Link>
      </div>
      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={setStatus}
        onAssigneeChange={setAssignee}
      />
      <p className="result-count">
        {visible.length} of {issues.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

import { FormEvent, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';

interface NewIssueProps {
  onCreate: (title: string) => void;
}

export default function NewIssue({ onCreate }: NewIssueProps) {
  const [title, setTitle] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const trimmedTitle = title.trim();

    if (!trimmedTitle) {
      setError('Title is required');
      return;
    }

    onCreate(trimmedTitle);
    navigate('/issues');
  }

  return (
    <section className="new-issue">
      <Link to="/issues" className="back-link">
        ← Back to issues
      </Link>
      <h1>New issue</h1>
      <form onSubmit={handleSubmit} noValidate>
        <label htmlFor="issue-title">Title</label>
        <input
          id="issue-title"
          name="title"
          type="text"
          value={title}
          onChange={(event) => {
            setTitle(event.target.value);
            if (error) setError('');
          }}
          aria-invalid={Boolean(error)}
          aria-describedby={error ? 'title-error' : undefined}
          autoFocus
        />
        {error && (
          <p className="form-error" id="title-error" role="alert">
            {error}
          </p>
        )}
        <div className="form-actions">
          <button type="submit" className="button button--primary">
            Create issue
          </button>
          <Link to="/issues" className="button button--secondary">
            Cancel
          </Link>
        </div>
      </form>
    </section>
  );
}

