import { BrowserRouter, Navigate, NavLink, Route, Routes } from 'react-router-dom';
import Dashboard from './pages/Dashboard';
import IssueDetail from './pages/IssueDetail';
import IssueList from './pages/IssueList';
import NewIssue from './pages/NewIssue';
import Settings from './pages/Settings';
import { IssueStoreProvider } from './data/IssueStore';

export default function App() {
  return (
    <BrowserRouter>
      <IssueStoreProvider>
        <header className="topbar">
          <span className="brand">Trackline</span>
          <nav>
            <NavLink to="/" end>
              Dashboard
            </NavLink>
            <NavLink to="/issues">Issues</NavLink>
            <NavLink to="/settings">Settings</NavLink>
          </nav>
        </header>
        <main className="page">
          <Routes>
            <Route path="/" element={<Dashboard />} />
            <Route path="/issues" element={<IssueList />} />
            <Route path="/issues/new" element={<NewIssue />} />
            <Route path="/issues/:id" element={<IssueDetail />} />
            <Route path="/settings" element={<Settings />} />
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </main>
      </IssueStoreProvider>
    </BrowserRouter>
  );
}

import { createContext, useContext, useState, type ReactNode } from 'react';
import { issues as initialIssues, type Issue } from './issues';

type NewIssue = Pick<Issue, 'title'> & Partial<Pick<Issue, 'description'>>;

interface IssueStoreValue {
  issues: Issue[];
  addIssue: (issue: NewIssue) => Issue;
}

const IssueStoreContext = createContext<IssueStoreValue | null>(null);

export function IssueStoreProvider({ children }: { children: ReactNode }) {
  const [issues, setIssues] = useState<Issue[]>(initialIssues);

  const addIssue = ({ title, description = '' }: NewIssue) => {
    const issue: Issue = {
      id: Math.max(0, ...issues.map((candidate) => candidate.id)) + 1,
      title,
      description,
      status: 'open',
      assignee: 'Unassigned',
      tags: [],
      createdAt: new Date().toISOString().slice(0, 10),
    };

    setIssues((current) => [issue, ...current]);
    return issue;
  };

  return (
    <IssueStoreContext.Provider value={{ issues, addIssue }}>
      {children}
    </IssueStoreContext.Provider>
  );
}

export function useIssueStore() {
  const store = useContext(IssueStoreContext);
  if (!store) throw new Error('useIssueStore must be used inside IssueStoreProvider');
  return store;
}

