import { useState } from 'react';
import { Link } from 'react-router-dom';
import FilterBar from '../components/FilterBar';
import IssueCard from '../components/IssueCard';
import { useIssueStore } from '../data/IssueStore';

export default function IssueList() {
  const { issues } = useIssueStore();
  const [status, setStatus] = useState('all');
  const [assignee, setAssignee] = useState('all');

  const visible = issues.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  return (
    <section>
      <div className="page-heading">
        <h1>Issues</h1>
        <Link to="/issues/new" className="button button--primary">
          New issue
        </Link>
      </div>
      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={setStatus}
        onAssigneeChange={setAssignee}
      />
      <p className="result-count">
        {visible.length} of {issues.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

import { useState, type FormEvent } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useIssueStore } from '../data/IssueStore';

export default function NewIssue() {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [titleError, setTitleError] = useState('');
  const { addIssue } = useIssueStore();
  const navigate = useNavigate();

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const trimmedTitle = title.trim();

    if (!trimmedTitle) {
      setTitleError('Title is required.');
      return;
    }

    addIssue({ title: trimmedTitle, description: description.trim() });
    navigate('/issues');
  }

  return (
    <section className="new-issue">
      <Link to="/issues" className="back-link">
        ← All issues
      </Link>
      <h1>New issue</h1>
      <form onSubmit={handleSubmit} noValidate>
        <label htmlFor="issue-title">
          Title <span aria-hidden="true">*</span>
        </label>
        <input
          id="issue-title"
          name="title"
          type="text"
          value={title}
          onChange={(event) => {
            setTitle(event.target.value);
            if (titleError) setTitleError('');
          }}
          aria-required="true"
          aria-invalid={Boolean(titleError)}
          aria-describedby={titleError ? 'title-error' : undefined}
          autoFocus
        />
        {titleError && (
          <p className="field-error" id="title-error" role="alert">
            {titleError}
          </p>
        )}

        <label htmlFor="issue-description">Description</label>
        <textarea
          id="issue-description"
          name="description"
          rows={6}
          value={description}
          onChange={(event) => setDescription(event.target.value)}
        />

        <div className="form-actions">
          <button type="submit" className="button button--primary">
            Create issue
          </button>
          <Link to="/issues" className="button">
            Cancel
          </Link>
        </div>
      </form>
    </section>
  );
}

