import { FormEvent, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import type { Issue } from '../data/issues';

interface NewIssueProps {
  onCreate: (issue: Omit<Issue, 'id' | 'createdAt'>) => void;
}

export default function NewIssue({ onCreate }: NewIssueProps) {
  const navigate = useNavigate();
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [titleError, setTitleError] = useState('');

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const trimmedTitle = title.trim();

    if (!trimmedTitle) {
      setTitleError('Title is required.');
      return;
    }

    onCreate({
      title: trimmedTitle,
      description: description.trim(),
      status: 'open',
      assignee: 'Unassigned',
      tags: [],
    });
    navigate('/issues');
  }

  return (
    <section className="new-issue">
      <Link to="/issues" className="back-link">
        ← All issues
      </Link>
      <h1>New issue</h1>
      <form onSubmit={handleSubmit} noValidate>
        <div className="form-field">
          <label htmlFor="issue-title">Title</label>
          <input
            id="issue-title"
            name="title"
            value={title}
            onChange={(event) => {
              setTitle(event.target.value);
              if (titleError) setTitleError('');
            }}
            aria-invalid={Boolean(titleError)}
            aria-describedby={titleError ? 'title-error' : undefined}
            autoFocus
          />
          {titleError && (
            <p className="field-error" id="title-error" role="alert">
              {titleError}
            </p>
          )}
        </div>

        <div className="form-field">
          <label htmlFor="issue-description">Description</label>
          <textarea
            id="issue-description"
            name="description"
            value={description}
            onChange={(event) => setDescription(event.target.value)}
            rows={6}
          />
        </div>

        <div className="form-actions">
          <button type="submit" className="button button--primary">
            Create issue
          </button>
          <Link to="/issues" className="button button--secondary">
            Cancel
          </Link>
        </div>
      </form>
    </section>
  );
}

